@mmahdigh 

``Info``
Phone: iPhone 7 128GB(Physical)
OS: iOS 13.1.3

``Setps``
1.  react-native init demo
2. modify demo/App.js just like 
```javascript
import React, {PureComponent} from 'react';
import {
    SafeAreaView,
    ScrollView,
    View,
    Text,
    StatusBar,
} from 'react-native';

class App extends PureComponent {
    constructor(props) {
        super(props);
        this.state = {
            num: 0
        }
    }

    componentDidMount(): * {
        this.timer = setInterval(() => {
            this.setState({
                num: this.state.num + 1
            })
        }, 1000)
    }

    render(): boolean | number | string | React$Element<*> | React$Portal | Iterable | null {
        return (
            <>
                <StatusBar barStyle="dark-content"/>
                <SafeAreaView>
                    <ScrollView
                        contentInsetAdjustmentBehavior="automatic"
                       >
                      <View>
                        <Text>{this.state.num}</Text>
                      </View>
                    </ScrollView>
                </SafeAreaView>
            </>
        )
    }
}

export default App;
```
3. run debug/release on the physical device
4. app background with the device not lockscreen OR foreground with the device lockscreen
5. wait just about one minutes or more, app crash

> Android is OK
